<?php $day=Warehouse::date((string)($_GET['day']??date('Y-m-d')));$dockId=(int)($_GET['dock_id']??0); ?>
<div class="page-heading"><div><p class="context">Planification</p><h1>Quais & rendez-vous</h1><p>Réservez les ressources du site et suivez leur disponibilité.</p></div><div class="actions"><?php if(Auth::can($user,'planning')): ?><a class="button" href="/?page=catalog&t=appointment&new=1">Nouveau rendez-vous</a><?php endif; ?><a class="button secondary" href="<?= h(url($_GET?:['page'=>'planning'])) ?>">Actualiser</a></div></div>
<form class="filters" method="get"><input type="hidden" name="page" value="planning"><?php inputField('day','Journée',$day,'date');selectField('dock_id','Quai',$catalog->options('dock'),$dockId,true); ?><button>Afficher</button><a href="/?page=planning">Aujourd’hui</a></form>
<p class="muted" data-refresh>État actuel des quais · Actualisation toutes les 30 secondes hors saisie.</p><div class="dock-grid"><?php foreach($reports->docks($day) as $d):if($dockId&&$d['id']!=$dockId)continue; ?><article class="dock-bay"><div class="bay-code"><?= h($d['code']) ?></div><div class="bay-door" aria-hidden="true"></div><h2><?= h($d['name']) ?></h2><?= badge($d['live_state']) ?><p><?= h($d['appointments']) ?> créneaux ce jour</p><small><?= h($d['type']) ?> · <?php $eq=$db->all('SELECT e.name FROM equipment e JOIN dock_equipment de ON de.equipment_id=e.id WHERE de.dock_id=?',[$d['id']]);echo h(implode(', ',array_column($eq,'name'))); ?></small></article><?php endforeach; ?></div>
<section class="panel"><h2>Créneaux du <?= h((new DateTimeImmutable($day))->format('d/m/Y')) ?></h2><?php $appointments=$db->all('SELECT a.*,d.code dock_code,v.plate,c.name carrier_name,p.name driver_name FROM appointment a JOIN dock d ON d.id=a.dock_id JOIN vehicle v ON v.id=a.vehicle_id JOIN carrier c ON c.id=v.carrier_id JOIN driver p ON p.id=a.driver_id WHERE a.starts_at<? AND a.ends_at>?'.($dockId?' AND a.dock_id=?':'').' ORDER BY a.starts_at',array_filter([(new DateTimeImmutable($day))->modify('+1 day')->format('Y-m-d'),$day,$dockId?:null],fn($v)=>$v!==null)); ?>
<div class="table-scroll"><table><thead><tr><th>Rendez-vous</th><th>Créneau</th><th>Quai</th><th>Transporteur / camion</th><th>Opération</th><th>État</th><th class="no-print">Actions</th></tr></thead><tbody><?php foreach($appointments as $a): ?><tr><td><?= h($a['reference']) ?></td><td><?= h(substr($a['starts_at'],11,5).' – '.substr($a['ends_at'],11,5)) ?></td><td><?= h($a['dock_code']) ?></td><td><?= h($a['carrier_name']) ?><small><?= h($a['plate'].' / '.$a['driver_name']) ?></small></td><td><?= h($a['operation']) ?></td><td><?= badge($a['status']) ?></td><td class="row-actions no-print"><?php if(Auth::can($user,'planning')&&$a['status']==='active'): ?><a href="<?= h(url(['page'=>'catalog','t'=>'appointment','edit'=>$a['id']])) ?>">Modifier</a><?php startForm('cancel_appointment',['id'=>$a['id']]); ?><button class="danger-link" data-confirm="Annuler ce rendez-vous ?">Annuler</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$appointments): ?><p class="empty">Aucun rendez-vous pour cette sélection.</p><?php endif; ?></section>
<?php if(Auth::can($user,'planning')): ?><a href="/?page=catalog&t=dock_downtime">Gérer les indisponibilités</a><?php endif; ?>
